    float MinSlope = 0.0f;

    UPROPERTY(EditAnywhere, Category = "Settings")
    float MaxSlope = 45.0f;

    virtual TArray<FPCGPinProperties> OutputPinProperties() const override
    {
        return { FPCGPinProperties(PCGPinConstants::DefaultOutputLabel, EPCGDataType::Surface) };
    }

protected:
    virtual FPCGElementPtr CreateElement() const override;
};

// PCG Executor
void UPCGMySpawnerElement::Execute(const FPCGContext* InContext)
{
    // 1. Get input points (from landscape or volume)
    // 2. Filter by slope angle and noise
    // 3. Spawn instances within radius
    // 4. Output to PCGVolume

    const UPCGPointData* InputData = Context->GetInputData();
    UPCGPointData* OutputData = NewObject<UPCGPointData>();
    TArray<FPCGPoint>& Points = OutputData->GetMutablePoints();

    for (const FPCGPoint& Point : InputData->GetPoints())
    {
        if (Points.Num() >= SpawnCount) break;
        float Noise = FMath::PerlinNoise2D(FVector2D(Point.Transform.GetLocation()));
        if (Noise > 0.3f)
        {
            Points.Add(Point);
        }
    }

    Context->SetOutputData(OutputData);
}

