// Mass processor (logic)
UCLASS()
class UMassMoveProcessor : public UMassProcessor
{
    GENERATED_BODY()

public:
    UMassMoveProcessor()
    {
        bRequiresGameThreadExecution = false;
        ExecutionFlags = (int32)EProcessorExecutionFlags::All;
    }

    virtual void ConfigureQueries(const FMassEntityQueryBuilders& QueryBuilders) override
    {
        EntityQuery.AddRequirement<FMoverMassFragment>(EMassFragmentPresence::All);
        EntityQuery.AddRequirement<FTransformFragment>(EMassFragmentPresence::All);
    }

    virtual void Execute(FMassEntityManager& EntityManager,
                         FMassExecutionContext& Context) override
    {
        EntityQuery.ForEachEntityChunk(EntityManager, Context,
            [](FMassExecutionContext& Ctx)
        {
            auto& MoveList = Ctx.GetMutableFragmentView<FMoverMassFragment>();
            auto& TransformList = Ctx.GetMutableFragmentView<FTransformFragment>();
            const float DeltaTime = Ctx.GetDeltaTimeSeconds();

            for (int32 i = 0; i < Ctx.GetNumEntities(); ++i)
            {
                FVector Direction = (MoveList[i].TargetLocation -
                    TransformList[i].GetTransform().GetLocation()).GetSafeNormal();

                TransformList[i].GetMutableTransform().AddToTranslation(
                    Direction * MoveList[i].Speed * DeltaTime
                );
            }
        });
    }

    FMassEntityQuery EntityQuery;
};

