class AMyPlayerController : public APlayerController
{
    GENERATED_BODY()

public:
    virtual void BeginPlay() override
    {
        Super::BeginPlay();

        if (auto* Subsystem = ULocalPlayer::GetSubsystem<
                UEnhancedInputLocalPlayerSubsystem>(GetLocalPlayer()))
        {
            Subsystem->AddMappingContext(DefaultMappingContext, 0);
        }
    }

    void SetupPlayerInputComponent(UInputComponent* PlayerInputComponent) override
    {
        Super::SetupPlayerInputComponent(PlayerInputComponent);

        if (auto* EnhancedInput = Cast<UEnhancedInputComponent>(PlayerInputComponent))
        {
            EnhancedInput->BindAction(MoveAction, ETriggerEvent::Triggered, this, &AMyPlayerController::Move);
            EnhancedInput->BindAction(LookAction, ETriggerEvent::Triggered, this, &AMyPlayerController::Look);
            EnhancedInput->BindAction(JumpAction, ETriggerEvent::Started, this, &AMyPlayerController::Jump);
            EnhancedInput->BindAction(SprintAction, ETriggerEvent::Triggered, this, &AMyPlayerController::Sprint);
            EnhancedInput->BindAction(InteractAction, ETriggerEvent::Started, this, &AMyPlayerController::Interact);
        }
    }

    void Move(const FInputActionValue& Value)
    {
        FVector2D MoveVector = Value.Get<FVector2D>();
        if (Controller)
        {
            const FRotator YawRot(0, Controller->GetControlRotation().Yaw, 0);
            FVector Forward = FRotationMatrix(YawRot).GetUnitAxis(EAxis::X);
            FVector Right = FRotationMatrix(YawRot).GetUnitAxis(EAxis::Y);
            GetPawn()->AddMovementInput(Forward, MoveVector.Y);
            GetPawn()->AddMovementInput(Right, MoveVector.X);
        }
    }

    void Look(const FInputActionValue& Value)
    {
        FVector2D LookVector = Value.Get<FVector2D>();
        AddYawInput(LookVector.X);
        AddPitchInput(LookVector.Y);
    }

