    ACineCameraActor* CinematicCamera;

    UFUNCTION(BlueprintCallable, Category = "Cinematics")
    void PlayCutscene()
    {
        if (!CutsceneSequence) return;

        auto* Player = GetWorld()->GetFirstPlayerController();
        if (!Player) return;

        // Create sequence actor and play
        ALeverSequenceActor* SeqActor;
        auto* MovieScene = CutsceneSequence->GetMovieScene();

        ULevelSequencePlayer* PlayerActor = ULevelSequencePlayer::CreateLevelSequencePlayer(
            GetWorld(),
            CutsceneSequence,
            FMovieSceneSequencePlaybackSettings(),
            SeqActor
        );

        if (PlayerActor)
        {
            // Blend to cinematic camera
            auto* CameraManager = Player->PlayerCameraManager;
            if (CinematicCamera)
            {
                CameraManager->SetViewTarget(CinematicCamera, FViewTargetTransitionParams());
            }

            PlayerActor->OnFinished.AddDynamic(this, &ASequencerController::OnCutsceneEnd);
            PlayerActor->Play();
        }
    }

    UFUNCTION()
    void OnCutsceneEnd()
    {
        // Return to player camera
        if (auto* Player = GetWorld()->GetFirstPlayerController())
        {
            auto* Pawn = Player->GetPawn();
            if (Pawn)
            {
                Player->SetViewTarget(Pawn, FViewTargetTransitionParams());
            }
        }
    }

    // Take Recorder: Window > Take Recorder
    // Record actor transforms, camera movement, and audio in real-time

